import{_ as i,o as n,c as a,ag as t}from"./chunks/framework.PVHj0As1.js";const c=JSON.parse('{"title":"17-Unit类型和Nothing类型","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/17-Unit类型和Nothing类型/17-Unit类型和Nothing类型.md","filePath":"仓颉入门到实战/17-Unit类型和Nothing类型/17-Unit类型和Nothing类型.md","lastUpdated":1734827919000,"__rawMarkdown":"# 17-Unit类型和Nothing类型\\n\\n## Unit类型\\n\\n对于那些只关心副作用而不关心值的表达式，它们的类型是 `Unit`。例如，`print` 函数、赋值表达式、复合赋值表达式、自增和自减表达\\n\\n式、循环表达式，它们的类型都是 `Unit`。\\n\\n`Unit` 类型只有一个值，也是它的字面量：`()`。**除了赋值、判等和判不等外**，`Unit` 类型不支持其他操作。\\n\\n比如：\\n\\n```javascript\\n    let a = println(\\"试试\\") // 输出 \\"试试\\"\\n    println(a) // 输出 () \\n```\\n\\n比如：\\n\\n```javascript\\n    var a = 10\\n    var b = a++\\n    println(b) // 输出 () \\n```\\n\\n比如：\\n\\n```javascript\\n    var a = 10\\n    var b = a++\\n    println(b == ()) // 输出 true  \\n```\\n\\n## Nothing类型\\n\\n> 目前编译器还不允许在使用类型的地方显式地使用 Nothing 类型。\\n\\n`Nothing` 是一种特殊的类型，它不包含任何值，并且 `Nothing` 类型是所有类型的子类型。\\n\\n`break`、`continue`、`return` 和 `throw` 表达式的类型是 `Nothing`，程序执行到这些表达式时，它们之后的代码将不会被执行。其中 \\n\\n`break`、`continue` 只能在循环体中使用，`return` 只能在函数体中使用。\\n\\n```javascript\\nmain() {\\n   let a = terminateProgram() // 返回 Nothing 类型\\n}\\n\\nfunc terminateProgram() {\\n    throw NegativeArraySizeException(\\"程序主动出错了\\")\\n}\\n```\\n\\n"}'),e={name:"仓颉入门到实战/17-Unit类型和Nothing类型/17-Unit类型和Nothing类型.md"};function p(l,s,h,r,k,d){return n(),a("div",null,[...s[0]||(s[0]=[t("",17)])])}const g=i(e,[["render",p]]);export{c as __pageData,g as default};
